using System.Collections.Generic;
using Unscrew.Core;
using UnityEngine;

namespace Unscrew.Game
{
    public enum UiMode
    {
        Menu,
        Game,
    }

    /// <summary>
    /// Screen router of the meta layer: menu, HUD, win/lose, shop, settings/pause, unlock popup, ad stub, toast.
    /// Talks to Core only through PlayerState (economy) and GameFlow (session + boosters); holds no game rules.
    /// Generated by the editor menu "Unscrew/Build UI".
    /// </summary>
    public sealed class UiRoot : MonoBehaviour
    {
        [SerializeField] private HudScreen hud;
        [SerializeField] private MenuScreen menu;
        [SerializeField] private WinScreen win;
        [SerializeField] private LoseScreen lose;
        [SerializeField] private ShopScreen shop;
        [SerializeField] private SettingsPopup settings;
        [SerializeField] private UnlockPopup unlock;
        [SerializeField] private AdOverlay ad;
        [SerializeField] private Toast toast;
        [SerializeField] private TransitionCurtain curtain;
        [SerializeField] private Onboarding onboarding;
        [Tooltip("Index = (int)BoosterType")]
        [SerializeField] private Sprite[] boosterIcons;
        [SerializeField] private Sprite coinSprite;
        [SerializeField] private Sprite coinsSprite;
        [Tooltip("Menu showcase: idle model rotation, degrees per second.")]
        [SerializeField] private float menuSpin = 14f;

        private readonly List<BoosterType> _unlocked = new List<BoosterType>();
        /// <summary>Boosters unlocked by the last win whose popup has not been shown yet (QA #1: never lost).</summary>
        private readonly List<BoosterType> _pendingUnlocks = new List<BoosterType>();
        private BoardInput _input;
        private bool _firstLoad = true;

        public GameFlow Flow { get; private set; }
        public PlayerState Player { get; private set; }
        public GameSettings Settings { get; private set; }
        public UiMode Mode { get; private set; }
        public Toast Toast => toast;
        public AdOverlay Ad => ad;
        public Sprite CoinSprite => coinSprite;
        public Sprite CoinsSprite => coinsSprite;
        public HudScreen Hud => hud;
        public MenuScreen Menu => menu;
        public WinScreen Win => win;
        public LoseScreen Lose => lose;
        public ShopScreen Shop => shop;
        public SettingsPopup SettingsPanel => settings;
        public UnlockPopup Unlock => unlock;
        public Onboarding Onboarding => onboarding;
        public TransitionCurtain Curtain => curtain;
        public bool Paused => Flow != null && Flow.Paused;

        /// <summary>A popup or full screen is over the board (onboarding hides).</summary>
        public bool AnyPopupOpen => win.IsOpen || lose.IsOpen || shop.IsOpen || settings.IsOpen || unlock.IsOpen || ad.IsOpen;

        /// <summary>
        /// Toast in a fixed spot that never covers cards or buttons: above the bottom safe edge in the shop (as in the
        /// mockup), above the booster panel in game, above the level pill in the menu.
        /// </summary>
        public void ShowToast(string message)
        {
            toast.Show(message, shop.IsOpen ? UiTokens.Toast.BottomShop : Mode == UiMode.Menu ? UiTokens.Toast.BottomMenu : UiTokens.Toast.BottomGame);
        }

        public Sprite BoosterIcon(BoosterType t)
        {
            int i = (int)t;
            return boosterIcons != null && i < boosterIcons.Length ? boosterIcons[i] : null;
        }

        public void Bind(GameFlow flow, PlayerState player, GameSettings gameSettings, BoardInput input)
        {
            Flow = flow;
            Player = player;
            Settings = gameSettings;
            _input = input;

            hud.Bind(this);
            menu.Bind(this);
            win.Bind(this);
            lose.Bind(this);
            shop.Bind(this);
            settings.Bind(this);
            unlock.Bind(this);
            onboarding.Bind(this);
            curtain.gameObject.SetActive(false);
            flow.MinLoadingSeconds = curtain.FadeInTime + 0.02f;
            foreach (var p in new UiPanel[] { hud, menu, win, lose, shop, settings, unlock, ad }) p.gameObject.SetActive(false);
            toast.gameObject.SetActive(false);

            flow.OnLevelLoading += OnLevelLoading;
            flow.OnLevelStarted += _ => { player.Continue.ResetForLevel(); hud.Refresh(); curtain.Reveal(); };
            flow.OnMove += hud.Refresh;
            flow.OnDrillModeChanged += on => { hud.Refresh(); _input.VisibleBoltsOnly = on; };
            flow.OnWin += OnWin;
            flow.OnLose += _ =>
            {
                hud.Refresh();
                Feedback.Play(Sfx.Lose);
                Settings.Vibrate(30);
                lose.Open();
            };
            player.Inventory.Changed += (t, c) => hud.Refresh();
            player.Unlocks.Unlocked += _ => hud.Refresh();
            shop.Closed += () => { if (lose.IsOpen) lose.Refresh(); hud.Refresh(); };
            settings.Closed += () => SetPaused(false);
        }

        // ---------- navigation ----------

        /// <summary>Intro transition while the next layout is generated in the background ("Level N" in game, plain in the menu).</summary>
        private void OnLevelLoading(int level)
        {
            bool titled = Mode == UiMode.Game;
            curtain.Cover(titled ? "Level " + level : "", titled && DifficultyCurve.IsHardLevel(level), _firstLoad);
            _firstLoad = false;
        }

        /// <summary>Main menu over the current level, which spins slowly; board input and the tray are off.</summary>
        public void ShowMenu()
        {
            Mode = UiMode.Menu;
            CloseAll();
            Flow.StartLevel(Player.Progress.CurrentLevel);
            SetBoardVisible(false);
            menu.Open();
        }

        public void PlayFromMenu()
        {
            Mode = UiMode.Game;
            menu.Close();
            // Fresh build: resets the showcase rotation and the continue counter.
            Flow.StartLevel(Player.Progress.CurrentLevel);
            SetBoardVisible(true);
            hud.Open();
            hud.Refresh();
        }

        /// <summary>
        /// Next level from the win screen (or QA skip). Closes every popup over the board, pause included; closing the win
        /// screen mid coin-flight still shows the unlock popup (it opens under the level intro and stays after it).
        /// </summary>
        public void NextLevel()
        {
            CloseGamePopups();
            Flow.StartLevel(Player.Progress.CurrentLevel);
            hud.Refresh();
            ShowPendingUnlocks();
        }

        public void RestartLevel()
        {
            CloseGamePopups();
            Flow.Restart();
            ShowPendingUnlocks();
        }

        public void OpenShop() => shop.Open();
        public void OpenSettings() => settings.Show(false);

        /// <summary>Pause: the board freezes (timeScale 0), taps and boosters are blocked, win/lose waits until resume.</summary>
        public void OpenPause()
        {
            if (Mode != UiMode.Game) return;
            Flow.CancelDrill();
            settings.Show(true);
            SetPaused(true);
        }

        private void SetPaused(bool paused)
        {
            Flow.Paused = paused;
            Time.timeScale = paused ? 0f : 1f;
            _input.enabled = !paused && Mode == UiMode.Game;
        }

        /// <summary>Popups that belong to the level being left (the unlock popup is kept: it must be seen).</summary>
        private void CloseGamePopups()
        {
            foreach (var p in new UiPanel[] { win, lose, shop, settings }) p.Close();
            SetPaused(false);
        }

        private void CloseAll()
        {
            // unlock first: closing the win screen mid coin-flight reopens it with the pending boosters.
            foreach (var p in new UiPanel[] { unlock, hud, win, lose, shop, settings, ad }) p.Close();
            SetPaused(false);
        }

        private void SetBoardVisible(bool playing)
        {
            _input.enabled = playing;
            Flow.Presenter.Tray.gameObject.SetActive(playing);
            Flow.Presenter.Level.AutoSpin = playing ? 0f : menuSpin;
            // The model fits the menu turntable area or the gameplay area (UiLayout zones).
            Flow.Presenter.Level.MenuFraming = !playing;
        }

        // ---------- boosters ----------

        public void OnBoosterClicked(BoosterType type)
        {
            var button = hud.Get(type);
            if (Player.Unlocks.IsUnlocked(type)) onboarding.MarkTipSeen(type);
            if (!Player.Unlocks.IsUnlocked(type))
            {
                button.Nudge();
                ShowToast("Unlocks at level " + Player.Unlocks.GetUnlockLevel(type));
                return;
            }
            if (type == BoosterType.Drill && Flow.DrillMode)
            {
                Flow.CancelDrill();
                return;
            }
            if (Player.Inventory.GetCount(type) <= 0)
            {
                OpenShop();
                return;
            }
            if (Flow.State != FlowState.Playing) return;
            if (!Flow.UseBooster(type))
            {
                button.Nudge();
                ShowToast(type == BoosterType.Magnet ? "No box to fill right now" : "Can't use it right now");
            }
        }

        // ---------- win / lose ----------

        private void OnWin(int level)
        {
            hud.Refresh();
            _unlocked.Clear();
            int reward = Player.CompleteLevel(Flow.IsHard, _unlocked);
            _pendingUnlocks.AddRange(_unlocked);
            Settings.Vibrate(40);
            // After the coins land, or as soon as the win screen closes (fast Next): see WinScreen.Close.
            win.Show(level, Flow.IsHard, reward, Player.Wallet.Coins, ShowPendingUnlocks);
        }

        private void ShowPendingUnlocks()
        {
            if (_pendingUnlocks.Count == 0) return;
            var types = new List<BoosterType>(_pendingUnlocks);
            _pendingUnlocks.Clear();
            unlock.Show(types, Player.Config.freeBoostersOnUnlock, null);
        }

        public void ContinueWithBooster()
        {
            if (Flow.State != FlowState.Lost) return;
            if (Flow.UseBooster(BoosterType.ExtraSlot) && Flow.State == FlowState.Playing) lose.Close();
            else lose.Refresh();
        }

        public void ContinueForCoins()
        {
            if (Flow.State != FlowState.Lost || !Flow.CanReviveWithHole()) return;
            if (!Player.Continue.CanAfford)
            {
                lose.NudgeContinue();
                ShowToast("Not enough coins");
                OpenShop();
                return;
            }
            if (!Player.Continue.TryPay()) return;
            Flow.ReviveWithHole();
            lose.Close();
        }
    }
}
